HO = WO = 32

def make_S():
    # S_s: (HO*WO) x (H*W) nearest-neighbor selector
    S = torch.zeros(HO * WO, H * W)
    for i in range(HO):
        for j in range(WO):
            si, sj = i * H // HO, j * W // WO
            S[i * WO + j, si * W + sj] = 1.0
    # block-diagonal per channel: (C*HW) x (C*HWo)
    Sbig = torch.zeros(C * H * W, C * HO * WO)
    for c in range(C):
        Sbig[c * H * W:(c + 1) * H * W, c * HO * WO:(c + 1) * HO * WO] = S
    return Sbig.t().contiguous()  # B for gemm (transB)

S_T = make_S()

